import { afterEach, expect, it } from "vitest";
import { Broker } from "../src/server.js";
import { Raw, until } from "./helpers.js";

const brokers: Broker[] = [];
const raws: Raw[] = [];
afterEach(async () => {
  for (const r of raws.splice(0)) r.close();
  await Promise.all(brokers.splice(0).map((b) => b.close(500)));
});

async function startCluster(n: number) {
  const nodes = [];
  for (let i = 0; i < n; i++) {
    const broker = new Broker({ host: "127.0.0.1", port: 0, cluster: { port: 0, reconnectMs: 50 } });
    const a = await broker.listen();
    brokers.push(broker);
    nodes.push({ broker, port: a.port, clusterPort: a.clusterPort! });
  }
  for (const a of nodes) for (const b of nodes) if (a !== b) a.broker.addRoute(`127.0.0.1:${b.clusterPort}`);
  await until(() => nodes.every((x) => x.broker.stats().routes === n - 1), 5000);
  return nodes;
}

const count = (t: string) => (t.match(/MSG news/g) ?? []).length;

it("exactly once everywhere, receivers forward nothing", async () => {
  const [a, b, c] = await startCluster(3);
  const subs = await Promise.all([a!, b!, c!].map((n) => Raw.ready(n.port)));
  raws.push(...subs);
  for (const s of subs) s.send("SUB news 1\r\n");
  await Promise.all(subs.map((s) => s.sync()));
  await until(() => a!.broker.peerInterest("news") === 2);   // RS+ has arrived from B and C
  const pub = await Raw.ready(a!.port);
  raws.push(pub);
  for (let i = 0; i < 100; i++) pub.send(`PUB news 1\r\n${i % 10}\r\n`);
  await pub.sync();
  await until(() => subs.every((s) => count(s.received) >= 100), 5000);
  await new Promise((r) => setTimeout(r, 100));            // give late duplicates a chance
  for (const s of subs) expect(count(s.received)).toBe(100);
  expect(a!.broker.stats().routeOutMsgs).toBe(200);
  expect(b!.broker.stats().routeOutMsgs).toBe(0);
  expect(c!.broker.stats().routeOutMsgs).toBe(0);
});
